import React from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  Button,
  Code,
  useClipboard,
  useToast,
  useColorModeValue,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Badge,
} from '@chakra-ui/react';
import { FaCopy, FaExternalLinkAlt } from 'react-icons/fa';

const Contract = () => {
  const { onCopy } = useClipboard('YOUR_CONTRACT_ADDRESS');
  const toast = useToast();
  const bgColor = useColorModeValue('white', 'gray.800');
  const textColor = useColorModeValue('gray.600', 'gray.300');

  const contractInfo = {
    address: 'YOUR_CONTRACT_ADDRESS',
    network: 'Solana Mainnet',
    verified: true,
    creator: '0x1234...5678',
    totalSupply: '1,000,000,000 SOLDROP',
    holders: '1,234',
  };

  const recentTransactions = [
    { hash: '0xabc...123', type: 'Transfer', amount: '1000 SOLDROP', time: '2 mins ago' },
    { hash: '0xdef...456', type: 'Reward', amount: '0.5 SOL', time: '5 mins ago' },
    { hash: '0xghi...789', type: 'Stake', amount: '500 SOLDROP', time: '10 mins ago' },
  ];

  const handleCopy = () => {
    onCopy();
    toast({
      title: 'Copied!',
      description: 'Contract address copied to clipboard',
      status: 'success',
      duration: 2000,
      isClosable: true,
    });
  };

  return (
    <Box bg={bgColor} minH="100vh" py={20}>
      <Container maxW="container.xl">
        <VStack spacing={12} align="stretch">
          <Box textAlign="center">
            <Heading as="h1" size="2xl" mb={6}>
              Smart Contract
            </Heading>
            <Text fontSize="xl" color={textColor} maxW="800px" mx="auto">
              Interact with the SolDrop smart contract. View contract details,
              recent transactions, and perform actions directly on the blockchain.
            </Text>
          </Box>

          <Box
            p={8}
            borderRadius="lg"
            boxShadow="xl"
            bg={useColorModeValue('white', 'gray.700')}
          >
            <VStack spacing={6} align="stretch">
              <Box>
                <Heading size="md" mb={4}>Contract Information</Heading>
                <Table variant="simple">
                  <Tbody>
                    <Tr>
                      <Td fontWeight="bold">Address</Td>
                      <Td>
                        <Code>{contractInfo.address}</Code>
                        <Button
                          size="sm"
                          ml={2}
                          leftIcon={<FaCopy />}
                          onClick={handleCopy}
                          variant="ghost"
                        >
                          Copy
                        </Button>
                      </Td>
                    </Tr>
                    <Tr>
                      <Td fontWeight="bold">Network</Td>
                      <Td>{contractInfo.network}</Td>
                    </Tr>
                    <Tr>
                      <Td fontWeight="bold">Status</Td>
                      <Td>
                        <Badge colorScheme={contractInfo.verified ? 'green' : 'red'}>
                          {contractInfo.verified ? 'Verified' : 'Unverified'}
                        </Badge>
                      </Td>
                    </Tr>
                    <Tr>
                      <Td fontWeight="bold">Total Supply</Td>
                      <Td>{contractInfo.totalSupply}</Td>
                    </Tr>
                    <Tr>
                      <Td fontWeight="bold">Holders</Td>
                      <Td>{contractInfo.holders}</Td>
                    </Tr>
                  </Tbody>
                </Table>
              </Box>

              <Box>
                <Heading size="md" mb={4}>Recent Transactions</Heading>
                <Table variant="simple">
                  <Thead>
                    <Tr>
                      <Th>Hash</Th>
                      <Th>Type</Th>
                      <Th>Amount</Th>
                      <Th>Time</Th>
                    </Tr>
                  </Thead>
                  <Tbody>
                    {recentTransactions.map((tx, index) => (
                      <Tr key={index}>
                        <Td>
                          <Code>{tx.hash}</Code>
                        </Td>
                        <Td>{tx.type}</Td>
                        <Td>{tx.amount}</Td>
                        <Td>{tx.time}</Td>
                      </Tr>
                    ))}
                  </Tbody>
                </Table>
              </Box>

              <Box textAlign="center" pt={4}>
                <Button
                  leftIcon={<FaExternalLinkAlt />}
                  colorScheme="blue"
                  size="lg"
                  onClick={() => window.open(`https://solscan.io/token/${contractInfo.address}`, '_blank')}
                >
                  View on Solscan
                </Button>
              </Box>
            </VStack>
          </Box>
        </VStack>
      </Container>
    </Box>
  );
};

export default Contract; 