import React from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  HStack,
  Circle,
  useColorModeValue,
  Divider,
} from '@chakra-ui/react';
import { FaCheckCircle, FaClock, FaRocket } from 'react-icons/fa';

type MilestoneStatus = 'completed' | 'current' | 'future';

const Roadmap = () => {
  const bgColor = useColorModeValue('white', 'gray.800');
  const textColor = useColorModeValue('gray.600', 'gray.300');
  const completedColor = useColorModeValue('green.500', 'green.400');
  const currentColor = useColorModeValue('blue.500', 'blue.400');
  const futureColor = useColorModeValue('gray.400', 'gray.600');
  const circleBg = useColorModeValue('white', 'gray.700');
  const dividerColor = useColorModeValue('gray.200', 'gray.700');
  const titleColor = useColorModeValue('blue.600', 'blue.400');

  const milestones = [
    {
      phase: 'Phase 1',
      title: 'Project Launch',
      date: 'Q1 2024',
      status: 'completed' as MilestoneStatus,
      items: [
        'Smart contract development and audit',
        'Website launch',
        'Community building',
        'Initial token distribution',
      ],
    },
    {
      phase: 'Phase 2',
      title: 'Platform Development',
      date: 'Q2 2024',
      status: 'current' as MilestoneStatus,
      items: [
        'Staking platform launch',
        'Reward system implementation',
        'Mobile app development',
        'Partnership announcements',
      ],
    },
    {
      phase: 'Phase 3',
      title: 'Ecosystem Expansion',
      date: 'Q3 2024',
      status: 'future' as MilestoneStatus,
      items: [
        'NFT integration',
        'Cross-chain bridges',
        'DAO governance implementation',
        'Advanced trading features',
      ],
    },
    {
      phase: 'Phase 4',
      title: 'Global Adoption',
      date: 'Q4 2024',
      status: 'future' as MilestoneStatus,
      items: [
        'Major exchange listings',
        'Enterprise partnerships',
        'Advanced analytics dashboard',
        'Global marketing campaign',
      ],
    },
  ];

  const getStatusIcon = (status: MilestoneStatus) => {
    switch (status) {
      case 'completed':
        return <FaCheckCircle color={completedColor} />;
      case 'current':
        return <FaRocket color={currentColor} />;
      default:
        return <FaClock color={futureColor} />;
    }
  };

  return (
    <Box bg={bgColor} minH="100vh" py={20}>
      <Container maxW="container.xl">
        <VStack spacing={12} align="stretch">
          <Box textAlign="center">
            <Heading as="h1" size="2xl" mb={6}>
              Project Roadmap
            </Heading>
            <Text fontSize="xl" color={textColor} maxW="800px" mx="auto">
              Our journey to revolutionize the Solana ecosystem with innovative
              token rewards and community-driven development.
            </Text>
          </Box>

          <VStack spacing={8} align="stretch">
            {milestones.map((milestone, index) => (
              <Box key={index}>
                <HStack spacing={4} align="start">
                  <Circle
                    size="40px"
                    bg={circleBg}
                    boxShadow="lg"
                    display="flex"
                    alignItems="center"
                    justifyContent="center"
                  >
                    {getStatusIcon(milestone.status)}
                  </Circle>
                  <Box flex={1}>
                    <HStack justify="space-between" align="center" mb={2}>
                      <Heading size="md">{milestone.phase}</Heading>
                      <Text color={textColor} fontSize="sm">
                        {milestone.date}
                      </Text>
                    </HStack>
                    <Text
                      fontSize="lg"
                      fontWeight="bold"
                      color={titleColor}
                      mb={4}
                    >
                      {milestone.title}
                    </Text>
                    <VStack align="start" spacing={2}>
                      {milestone.items.map((item, itemIndex) => (
                        <Text key={itemIndex} color={textColor}>
                          • {item}
                        </Text>
                      ))}
                    </VStack>
                  </Box>
                </HStack>
                {index < milestones.length - 1 && (
                  <Divider
                    orientation="vertical"
                    borderLeftWidth="2px"
                    borderColor={dividerColor}
                    ml="20px"
                    h="40px"
                  />
                )}
              </Box>
            ))}
          </VStack>
        </VStack>
      </Container>
    </Box>
  );
};

export default Roadmap; 