import React from 'react';
import { Box, Container, Heading, Text, VStack, Button, Image, useColorModeValue } from '@chakra-ui/react';
import { FaWallet } from 'react-icons/fa';
import { useWallet } from '@solana/wallet-adapter-react';

const Connect = () => {
  const { connect, connected, publicKey } = useWallet();
  const bgColor = useColorModeValue('white', 'gray.800');
  const textColor = useColorModeValue('gray.600', 'gray.300');

  return (
    <Box bg={bgColor} minH="100vh" py={20}>
      <Container maxW="container.xl">
        <VStack spacing={12} align="center">
          <Box textAlign="center">
            <Heading as="h1" size="2xl" mb={6}>
              Connect Your Wallet
            </Heading>
            <Text fontSize="xl" color={textColor} maxW="800px" mx="auto">
              Connect your Solana wallet to start participating in the SolDrop ecosystem.
              Access exclusive features and manage your assets securely.
            </Text>
          </Box>

          <Box
            p={8}
            borderRadius="lg"
            boxShadow="xl"
            bg={useColorModeValue('white', 'gray.700')}
            w="full"
            maxW="600px"
          >
            <VStack spacing={6}>
              {!connected ? (
                <>
                  <Image
                    src="/solana-logo.png"
                    alt="Solana Logo"
                    boxSize="100px"
                    fallbackSrc="https://solana.com/static/img/solanaLogo.svg"
                  />
                  <Button
                    leftIcon={<FaWallet />}
                    colorScheme="blue"
                    size="lg"
                    onClick={() => connect()}
                    w="full"
                    maxW="300px"
                  >
                    Connect Wallet
                  </Button>
                  <Text color={textColor} textAlign="center">
                    Supported wallets: Phantom, Solflare, and more
                  </Text>
                </>
              ) : (
                <>
                  <Image
                    src="/solana-logo.png"
                    alt="Solana Logo"
                    boxSize="100px"
                    fallbackSrc="https://solana.com/static/img/solanaLogo.svg"
                  />
                  <Text fontSize="xl" fontWeight="bold">
                    Wallet Connected!
                  </Text>
                  <Text color={textColor}>
                    Address: {publicKey?.toBase58().slice(0, 4)}...
                    {publicKey?.toBase58().slice(-4)}
                  </Text>
                  <Text color={textColor} textAlign="center">
                    You can now access all features of the SolDrop platform
                  </Text>
                </>
              )}
            </VStack>
          </Box>

          <Box textAlign="center" mt={8}>
            <Heading as="h2" size="xl" mb={6}>
              Why Connect?
            </Heading>
            <VStack spacing={4} align="center">
              <Text color={textColor}>
                • Access exclusive features and rewards
              </Text>
              <Text color={textColor}>
                • Participate in governance decisions
              </Text>
              <Text color={textColor}>
                • Manage your digital assets securely
              </Text>
              <Text color={textColor}>
                • Join our growing community
              </Text>
            </VStack>
          </Box>
        </VStack>
      </Container>
    </Box>
  );
};

export default Connect; 